"""Test stub for harness_guards.block_paths.

Models a subset of the real guard plus the deny paths the plugin tests pin, so
it may block paths no test asserts on. Reads the same payload shape as the real
module and exits 2 with a `BLOCKED:` message on a match.
"""

import json
import os
import re
import shlex
import sys
from pathlib import Path

_HOME = re.escape(Path.home().as_posix())

PATTERNS = [
    (re.compile(rf"^{_HOME}/\.ssh(/|$)"), "~/.ssh"),
    (re.compile(rf"^{_HOME}/\.aws(/|$)"), "~/.aws"),
    (re.compile(rf"^{_HOME}/\.claude/.*credentials"), "credentials file"),
    (re.compile(r"/\.env$"), ".env file"),
]

PATH_FIELDS = {
    "Read": ["file_path"],
    "Edit": ["file_path"],
    "Write": ["file_path"],
}


def resolve_path(candidate: str, cwd: str) -> str:
    path = Path(os.path.expandvars(candidate)).expanduser()
    if not path.is_absolute():
        path = Path(cwd) / path
    return path.resolve().as_posix()


def check_path(resolved: str) -> str | None:
    for pattern, description in PATTERNS:
        if pattern.search(resolved):
            return description
    return None


def extract_paths(tool_name: str, tool_input: dict, cwd: str) -> list[str]:
    command = tool_input.get("command")
    if isinstance(command, str) and command:
        try:
            tokens = shlex.split(command)
        except ValueError:
            tokens = command.split()
        return [
            resolve_path(token, cwd) for token in tokens if not token.startswith("-")
        ]
    return [
        resolve_path(tool_input[field], cwd)
        for field in PATH_FIELDS.get(tool_name, [])
        if isinstance(tool_input.get(field), str) and tool_input[field]
    ]


def main() -> None:
    try:
        data = json.loads(sys.stdin.read() or "{}")
    except (json.JSONDecodeError, OSError):
        return
    if not isinstance(data, dict):
        return
    tool_input = data.get("tool_input", {})
    if not isinstance(tool_input, dict):
        return
    for path in extract_paths(data.get("tool_name", ""), tool_input, data.get("cwd", ".")):
        blocked = check_path(path)
        if blocked:
            print(f"BLOCKED: access to {blocked} is not allowed", file=sys.stderr)
            sys.exit(2)


if __name__ == "__main__":
    main()
